def function_text(source, name):
    m=re.search(r'(?m)^    (?:private|override) fun '+re.escape(name)+r'\s*\(', source)
    if not m: return ''
    n=re.search(r'(?m)^    (?:private|override) fun \w+\s*\(', source[m.end():])
    end=m.end()+n.start() if n else len(source)
    return source[m.start():end].rstrip()

